tape( 'if the number of output rows is less than or equal to `0`, the function returns the output array unchanged (full=true)', function test( t ) {
	var expected;
	var out;

	out = [ 0.0, 0.0, 0.0, 0.0 ];

	ghelmert( true, 0, out, 0, 1, 0 );

	expected = [ 0.0, 0.0, 0.0, 0.0 ];

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

